/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { HydrogenAtomScreen } from "../../src/hydrogen-atom/HydrogenAtomScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import LightAndAtomsColors from "../../src/LightAndAtomsColors.js";
import { LineSpectraScreen } from "../../src/line-spectra/LineSpectraScreen.js";
import { LightAndAtomsPreferencesModel } from "../../src/preferences/LightAndAtomsPreferencesModel.js";
import { EMSpectrumScreen } from "../../src/spectrum/EMSpectrumScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from lightAndAtomsQueryParameters.
  const simPreferences = new LightAndAtomsPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new EMSpectrumScreen(simPreferences, {
      name: stringManager.getScreenNames().spectrumStringProperty,
      tandem: Tandem.ROOT.createTandem("spectrumScreen"),
      backgroundColorProperty: LightAndAtomsColors.backgroundColorProperty,
    }),
    new HydrogenAtomScreen({
      name: stringManager.getScreenNames().hydrogenAtomStringProperty,
      tandem: Tandem.ROOT.createTandem("hydrogenAtomScreen"),
      backgroundColorProperty: LightAndAtomsColors.backgroundColorProperty,
    }),
    new LineSpectraScreen({
      name: stringManager.getScreenNames().lineSpectraStringProperty,
      tandem: Tandem.ROOT.createTandem("lineSpectraScreen"),
      backgroundColorProperty: LightAndAtomsColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { LightAndAtomsColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
